<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import PersonalizedWorkbench from '@/components/assistant/PersonalizedWorkbench.vue'
import { useAssistantWorkbenches } from '@/composables/useAssistantWorkbenches'
import { fetchAssistantState, saveAssistantState } from '@/api/assistant'
import { fetchDashboard } from '@/api/dashboard'
import { applyDashboard } from '@/data/farm'
import AgentIcon from '@/components/assistant/AgentIcon.vue'
import AssistantAnswer from '@/components/assistant/AssistantAnswer.vue'
import { getUser } from '@/api/auth'
import { createRun, listRuns, getRun, getEvents, cancelRun, retryRun, followupRun, type AgentRun, type AgentEvent } from '@/api/agent'

const router = useRouter()
const route = useRoute()
const runs = ref<AgentRun[]>([]), active = ref<AgentRun | null>(null), events = ref<AgentEvent[]>([])
const followupMode=ref(false)
const question = ref(''), error = ref(''), submitting = ref(false), cancelling = ref(false)
let timer: number | undefined, generation = 0, disposed = false
const busy = computed(() => !!active.value && ['QUEUED', 'RUNNING'].includes(active.value.status))
const states: Record<string, string> = { QUEUED: '等待执行', RUNNING: '正在执行', COMPLETED: '已完成', FAILED: '执行失败', CANCELLED: '已取消' }
const tools: Record<string, string> = { get_farm_context: '读取农场数据', retrieve_evidence: '检索农业资料', analyze_environment: '核验环境阈值', get_business_records:'查询业务与追溯记录', get_vision_records:'查询视觉检测记录' }
const suggestions = [
  { icon: 'chart', title: '农场状态分析', detail: '环境指标与异常概览', text: '分析农场当前环境与异常，列出依据和缺少的数据' },
  { icon: 'drop', title: '灌溉管理建议', detail: '核验墒情与配置阈值', text: '查询土壤湿度是否低于配置阈值，并给出灌溉建议' },
  { icon: 'book', title: '鸭梨采后管理', detail: '检索资料与适用条件', text: '检索鸭梨采后管理资料，说明现有证据是否足够' },
]
function payload(event: AgentEvent): Record<string, any> { try { return JSON.parse(event.payload) } catch { return {} } }
function label(event: AgentEvent) {
  const data = payload(event)
  if (event.type === 'model.started') return `正在生成 · 第 ${data.round} 轮`
  if (event.type.startsWith('tool.')) return `${tools[data.tool] || data.tool} · ${{ started: '执行中', completed: '已完成', failed: '失败' }[event.type.split('.')[1]] || ''}`
  return states[event.type.split('.')[1].toUpperCase()] || '任务已创建'
}
const taskPlan=computed(()=>events.value.filter(e=>e.type==='run.plan').flatMap(e=>payload(e).steps||[]))
async function continueTask(){followupMode.value=true;question.value='';await nextTick();inputElement.value?.focus()}
async function viewParent(){if(!active.value?.parentRunId)return;try{await select(await getRun(active.value.parentRunId))}catch(e){error.value=(e as Error).message}}
function exportTask(){if(!active.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify({schemaVersion:1,run:active.value,events:events.value},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`Agent任务-${active.value.id}.json`;link.click();URL.revokeObjectURL(url)}
const evidence = computed(() => events.value.filter(e => e.type === 'tool.completed' && payload(e).tool === 'retrieve_evidence').flatMap(e => payload(e).result?.evidence || []))
async function refreshList() { runs.value = await listRuns() }
async function select(run: AgentRun) {
  followupMode.value=false
  const version = ++generation
  window.clearTimeout(timer); if (window.innerWidth < 800) sidebarOpen.value = false; active.value = run; events.value = []; error.value = ''
  await poll(version)
}
async function poll(version: number) {
  const id = active.value?.id
  if (!id || disposed || version !== generation) return
  try {
    const [run, next] = await Promise.all([getRun(id), getEvents(id, events.value[events.value.length - 1]?.seq || 0)])
    if (disposed || version !== generation) return
    active.value = run; events.value.push(...next)
    if (['QUEUED', 'RUNNING'].includes(run.status)) timer = window.setTimeout(() => poll(version), 1200)
    else await refreshList()
  } catch (e) { if (version === generation) error.value = e instanceof Error ? e.message : '无法获取任务，点击重连' }
}
async function submit() {
  if (!question.value.trim() || submitting.value || busy.value) return
  submitting.value = true; error.value = ''
  try { const run = followupMode.value&&active.value ? await followupRun(active.value.id,question.value.trim()) : await createRun(question.value.trim(), route.query.farmId === 'farm-01' ? 'farm-01' : 'yantian-01'); question.value = ''; await refreshList(); await select(run) }
  catch (e) { error.value = e instanceof Error ? e.message : '无法创建任务' }
  finally { submitting.value = false }
}
async function cancel() {
  if (!active.value || cancelling.value) return
  cancelling.value = true
  try { await cancelRun(active.value.id); await poll(generation) }
  catch (e) { error.value = e instanceof Error ? e.message : '取消失败' }
  finally { cancelling.value = false }
}
function newTask() { followupMode.value=false; generation++; window.clearTimeout(timer); active.value = null; events.value = []; error.value = '' }
async function retry() { if(!active.value||submitting.value)return;submitting.value=true;error.value='';try{const run=await retryRun(active.value.id);await refreshList();await select(run)}catch(e){error.value=e instanceof Error?e.message:'重试失败'}finally{submitting.value=false} }
onMounted(async () => { try { await refreshList(); if (typeof route.query.prompt === 'string') { newTask(); question.value = route.query.prompt.slice(0,2000); await nextTick(); inputElement.value?.focus() } else if (runs.value[0]) await select(runs.value[0]) } catch (e) { error.value = e instanceof Error ? e.message : '无法读取任务' } })
onBeforeUnmount(() => { disposed = true; generation++; window.clearTimeout(timer) })
const sidebarOpen = ref(window.innerWidth >= 800), evidenceOpen = ref(false), settingsOpen = ref(false), search = ref(''), copied = ref(false)
const windowWidth = ref(window.innerWidth)
function resizeWindow() { if (windowWidth.value >= 800 && window.innerWidth < 800) sidebarOpen.value = false; windowWidth.value = window.innerWidth }
onMounted(() => window.addEventListener('resize', resizeWindow))
onBeforeUnmount(() => window.removeEventListener('resize', resizeWindow))
const theme = ref(localStorage.getItem('agric-agent-theme') || 'light')
const user = getUser()
const activeFarmLabel = computed(() => (active.value?.farmId || route.query.farmId) === 'farm-01' ? '原温室演示园' : '沧州盐碱地示范基地')
const inputElement = ref<HTMLTextAreaElement>()
const settingsDialog = ref<HTMLElement>()
let previousFocus: HTMLElement | null = null
watch(settingsOpen, async open => {
  if (open) { previousFocus = document.activeElement as HTMLElement; await nextTick(); settingsDialog.value?.querySelector<HTMLButtonElement>('button')?.focus() }
  else if (previousFocus?.isConnected) previousFocus.focus()
})
function trapFocus(event: KeyboardEvent) {
  const buttons = (event.currentTarget as HTMLElement)?.querySelectorAll<HTMLElement>('button:not(:disabled),select,input,a[href],textarea')
  if (!buttons?.length || event.key !== 'Tab') return
  const first = buttons[0], last = buttons[buttons.length - 1]
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
}
const filteredRuns = computed(() => runs.value.filter(run => run.question.toLowerCase().includes(search.value.toLowerCase())))
const groups = computed(() => {
  const today = new Date().toLocaleDateString()
  return [{ title: '今天', items: filteredRuns.value.filter(run => new Date(run.createdAt).toLocaleDateString() === today) }, { title: '之前', items: filteredRuns.value.filter(run => new Date(run.createdAt).toLocaleDateString() !== today) }].filter(group => group.items.length)
})
const toolSteps = computed(() => {
  const rows = new Map<string, { id: string; name: string; status: string; result?: any; message?: string }>()
  for (const event of events.value) {
    if (!event.type.startsWith('tool.')) continue
    const data = payload(event)
    rows.set(data.call_id, { id: data.call_id, name: data.tool, status: event.type.split('.')[1], result: data.result, message: data.message })
  }
  return [...rows.values()]
})
const elapsed = computed(() => {
  if (!events.value.length) return ''
  const last = events.value[events.value.length - 1]
  const seconds = Math.max(0, Math.round((new Date(last.timestamp).getTime() - new Date(events.value[0].timestamp).getTime()) / 1000))
  return seconds < 60 ? `${seconds} 秒` : `${Math.floor(seconds / 60)} 分 ${seconds % 60} 秒`
})
function toggleTheme() { theme.value = theme.value === 'dark' ? 'light' : 'dark'; localStorage.setItem('agric-agent-theme', theme.value) }
function useSuggestion(text: string) { question.value = text; inputElement.value?.focus() }
function onInputKey(event: KeyboardEvent) { if (event.key === 'Enter' && !event.shiftKey && !event.isComposing) { event.preventDefault(); void submit() } }
async function copyAnswer() { try { await navigator.clipboard.writeText(active.value?.answer || ''); copied.value = true; window.setTimeout(() => { copied.value = false }, 1800) } catch { error.value = '复制失败，请选中回答后复制' } }
function detailText(result: any) { return typeof result === 'string' ? result : JSON.stringify(result, null, 2) }
const panelDialog = ref<HTMLElement>()
const panelOpen = ref(false), panelReady = ref(false), panelSaving = ref(false), panelError = ref('')
const { ensureProjectWorkbench, workbenches, activeWorkbenchId, activeWorkbench, replaceWorkbenches, selectWorkbench, createWorkbench, addWidget, removeWidget, updateWidget, moveWidget, renameActiveWorkbench, duplicateActiveWorkbench, deleteActiveWorkbench, clearActiveWorkbench, toggleActivePinned } = useAssistantWorkbenches()
let saveTimer: number | undefined, panelRefreshTimer: number | undefined
onMounted(async () => {
  try { const state = await fetchAssistantState(); const saved = JSON.parse(state.workbenchesJson || '[]'); if (state.updatedAt || saved.length) replaceWorkbenches(saved); applyDashboard(await fetchDashboard('yantian-01')); panelReady.value = true; ensureProjectWorkbench() }
  catch(e) { panelError.value = e instanceof Error ? e.message : '工作面板加载失败' }
})
watch(workbenches, () => {
  if (!panelReady.value) return
  window.clearTimeout(saveTimer)
  saveTimer = window.setTimeout(async () => {
    panelSaving.value = true
    try { const latest = await fetchAssistantState(); await saveAssistantState(workbenches.value, JSON.parse(latest.conversationsJson || '[]')); panelError.value = '' }
    catch(e) { panelError.value = e instanceof Error ? e.message : '工作面板保存失败' }
    finally { panelSaving.value = false }
  }, 650)
}, { deep: true })
watch(panelOpen, async open => { if(open){ previousFocus = document.activeElement as HTMLElement; await nextTick(); panelDialog.value?.querySelector<HTMLButtonElement>('button')?.focus() } else if(previousFocus?.isConnected) previousFocus.focus() })
watch(panelOpen, open => { window.clearInterval(panelRefreshTimer); if(open) { const refresh = async () => { try { applyDashboard(await fetchDashboard('yantian-01')) } catch(e) { panelError.value = e instanceof Error ? e.message : '数据刷新失败' } }; void refresh(); panelRefreshTimer = window.setInterval(refresh, 30000) } })
onBeforeUnmount(() => window.clearInterval(panelRefreshTimer))
function openPanel() { panelOpen.value = true; if (windowWidth.value < 800) sidebarOpen.value = false }
function animateDetails(event: MouseEvent) {
  const summary = (event.target as HTMLElement).closest('summary')
  const detail = summary?.parentElement as HTMLDetailsElement | undefined
  if (!summary || !detail || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
  event.preventDefault()
  if (detail.dataset.animating) return
  const start = detail.getBoundingClientRect().height, closing = detail.open
  if (!closing) detail.open = true
  const end = closing ? summary.getBoundingClientRect().height : detail.getBoundingClientRect().height
  detail.dataset.animating = 'true'; detail.style.overflow = 'hidden'
  const animation = detail.animate({ height: [`${start}px`, `${end}px`] }, { duration: 260, easing: 'cubic-bezier(.22,1,.36,1)' })
  animation.onfinish = () => { detail.open = !closing; detail.style.overflow = ''; delete detail.dataset.animating }
}
</script>

<template>
  <div class="agent-app" :class="[{ 'sidebar-hidden': !sidebarOpen, 'details-visible': evidenceOpen }, theme]" @click="animateDetails" @keydown.esc="panelOpen = false; settingsOpen = false; evidenceOpen = false; sidebarOpen = windowWidth >= 800 ? sidebarOpen : false">
    <button v-if="sidebarOpen" class="sidebar-scrim" aria-label="关闭侧栏" @click="sidebarOpen = false" />
    <aside class="session-sidebar" aria-label="任务侧栏">
      <div class="sidebar-brand"><a href="/" class="brand"><span class="brand-symbol"><AgentIcon name="leaf" :size="23" /></span><span>盐田丰语<small>农业智能工作空间</small></span></a><button class="icon-button" aria-label="收起侧栏" title="收起侧栏" @click="sidebarOpen = false"><AgentIcon name="panel" :size="18" /></button></div>
      <button class="new-session" @click="newTask(); sidebarOpen = windowWidth >= 800"><AgentIcon name="plus" :size="18" /><span>新任务</span></button>
      <div class="session-search"><AgentIcon name="search" :size="15" /><input v-model="search" placeholder="搜索任务" aria-label="搜索任务历史" /><button v-if="search" class="icon-button" aria-label="清除搜索" @click="search = ''"><AgentIcon name="close" :size="13" /></button></div>
      <div class="session-list"><section v-for="group in groups" :key="group.title"><h3>{{ group.title }}</h3><button v-for="run in group.items" :key="run.id" class="session-row" :class="{ selected: active?.id === run.id }" @click="select(run)"><span class="session-status" :class="run.status.toLowerCase()" /><span>{{ run.question }}</span><AgentIcon v-if="active?.id === run.id" name="chevron" :size="13" /></button></section><div v-if="!filteredRuns.length" class="history-empty"><AgentIcon name="chat" :size="27" /><strong>{{ search ? '没有匹配的任务' : '从一个问题开始' }}</strong><p>{{ search ? '试试其他关键词' : '任务和执行记录会保存在这里' }}</p></div></div>
      <div class="sidebar-bottom"><button class="sidebar-link" @click="router.push('/crops')"><AgentIcon name="leaf" :size="17" />作物中心<AgentIcon name="chevron" :size="13" /></button><button class="sidebar-link" @click="openPanel"><AgentIcon name="panel" :size="17" />我的工作面板<span class="config-dot" /></button><button class="sidebar-link" @click="router.push('/workspaces/farm-01')"><AgentIcon name="grid" :size="17" />数据工作台<AgentIcon name="external" :size="13" /></button><button class="sidebar-link" @click="settingsOpen = !settingsOpen"><AgentIcon name="settings" :size="17" />运行配置<span class="config-dot" /></button><div class="user-row"><span class="user-avatar">{{ (user?.name || '用户').slice(0, 1) }}</span><span>{{ user?.name || '农场用户' }}<small>共享演示农场</small></span><button class="icon-button" :title="theme === 'light' ? '切换深色主题' : '切换浅色主题'" :aria-label="theme === 'light' ? '切换深色主题' : '切换浅色主题'" @click="toggleTheme"><AgentIcon :name="theme === 'light' ? 'moon' : 'sun'" :size="18" /></button></div></div>
    </aside>

    <div class="conversation-workspace">
      <header class="workspace-header"><div class="header-leading"><button v-if="!sidebarOpen" class="icon-button" aria-label="展开侧栏" title="展开侧栏" @click="sidebarOpen = true"><AgentIcon name="panel" /></button><span class="workspace-title">{{ active ? '智能问农' : '新任务' }}</span><span class="header-separator">/</span><span class="farm-label">{{ activeFarmLabel }}</span></div><div class="header-actions"><span class="demo-badge"><span />演示环境</span><button class="icon-button" :class="{ pressed: evidenceOpen }" title="查看任务依据" aria-label="查看任务依据" :aria-expanded="evidenceOpen" @click="evidenceOpen = !evidenceOpen"><AgentIcon name="book" :size="19" /><span v-if="evidence.length" class="count-dot">{{ evidence.length }}</span></button></div></header>

      <div class="conversation-body" :class="{ 'is-empty': !active }">
        <div v-if="!active" class="welcome-panel"><div class="welcome-mark"><AgentIcon name="leaf" :size="42" /></div><h1>今天，农场需要关注什么？</h1><p>我可以帮你分析农场数据、核验环境阈值、查找农技资料。</p><div class="welcome-context"><AgentIcon name="grid" :size="14" />{{ activeFarmLabel }}<span>共享演示数据</span></div></div>
        <div v-else class="transcript">
          <div class="user-message"><div>{{ active.question }}</div></div>
          <section class="assistant-turn"><div class="assistant-identity"><span class="assistant-symbol"><AgentIcon name="leaf" :size="18" /></span><strong>盐田丰语</strong><span>{{ active.model }}</span></div>
            <details class="process-group" :open="busy || active.status === 'FAILED'"><summary><span class="process-indicator" :class="{ spinning: busy, failed: active.status === 'FAILED' }"><AgentIcon :name="busy ? 'clock' : active.status === 'COMPLETED' ? 'check' : 'stop'" :size="15" /></span><span>{{ busy ? '正在处理任务' : active.status === 'COMPLETED' ? '已完成分析' : states[active.status] }}</span><span class="process-meta">{{ toolSteps.length }} 个工具<span v-if="elapsed"> · {{ elapsed }}</span></span><AgentIcon name="chevron" :size="14" /></summary><div class="process-content"><div v-if="taskPlan.length" class="task-plan"><strong>任务核验流程</strong><ol><li v-for="step in taskPlan" :key="step">{{ step }}</li></ol></div><div v-if="!toolSteps.length" class="model-status"><span class="activity-dot" />{{ active.status === 'QUEUED' ? '任务正在等待执行' : busy ? '模型正在解析任务，首次加载可能需要更长时间' : '未执行工具' }}</div><details v-for="step in toolSteps" :key="step.id" class="tool-step"><summary><span class="step-icon" :class="step.status"><AgentIcon :name="step.status === 'completed' ? 'check' : step.status === 'failed' ? 'close' : 'clock'" :size="14" /></span><span>{{ tools[step.name] || step.name }}</span><small>{{ step.status === 'completed' ? '完成' : step.status === 'failed' ? '失败' : '执行中' }}</small><AgentIcon name="chevron" :size="12" /></summary><div class="tool-detail"><p v-if="step.message">{{ step.message }}</p><pre v-if="step.result">{{ detailText(step.result) }}</pre><span v-else>等待工具返回结果</span></div></details><div v-if="busy && toolSteps.length && toolSteps.every(step => step.status !== 'started')" class="model-status"><span class="activity-dot" />正在根据工具结果组织回答</div></div></details>
            <div class="task-record-actions"><button v-if="active.parentRunId" class="text-button" @click="viewParent">查看原任务</button><button v-if="active.status==='COMPLETED'" class="text-button" @click="continueTask">继续追问</button><button class="text-button" @click="exportTask">导出任务记录</button><button v-if="active.status==='CANCELLED'" class="text-button" :disabled="submitting" @click="retry">重新执行</button></div><article v-if="active.answer" class="answer-content"><AssistantAnswer :content="active.answer" /></article>
            <div v-if="active.error" class="error-notice" role="alert"><strong>任务未能完成</strong><p>{{ active.error }}</p><button @click="retry">重新发起 <AgentIcon name="arrow" :size="14" /></button></div>
            <div v-if="active.answer" class="answer-toolbar"><button class="icon-button" :title="copied ? '已复制' : '复制回答'" :aria-label="copied ? '已复制' : '复制回答'" @click="copyAnswer"><AgentIcon :name="copied ? 'check' : 'copy'" :size="17" /></button><button class="text-button" @click="evidenceOpen = true"><AgentIcon name="book" :size="15" />{{ evidence.length ? `${evidence.length} 条资料依据` : '查看任务依据' }}</button><span>{{ copied ? '已复制到剪贴板' : '基于共享演示数据' }}</span></div>
          </section>
        </div>
        <div v-if="error" class="error-notice general-error" role="alert">{{ error }}<button v-if="active" @click="poll(generation)">重新连接</button></div>
      </div>

      <div class="composer-dock" :class="{ 'hero-dock': !active }"><p v-if="followupMode" class="followup-hint">正在追问当前任务 · 最多 1000 字 <button @click="followupMode=false">改为新任务</button></p><form class="composer-card" @submit.prevent="submit"><label for="agent-input" class="sr-only">输入农业任务</label><textarea id="agent-input" ref="inputElement" v-model="question" :maxlength="followupMode ? 1000 : 2000" rows="2" :placeholder="busy ? '任务执行中，可在上方查看进度…' : '描述你关心的农场问题…'" :disabled="busy || submitting" @keydown="onInputKey" /><div class="composer-controls"><button type="button" class="context-chip" @click="settingsOpen = !settingsOpen" :aria-expanded="settingsOpen"><AgentIcon name="leaf" :size="14" /><span>{{ active?.model || 'Qwen2.5 7B' }}</span><AgentIcon name="chevron" :size="11" /></button><span class="composer-hint">{{ question.length ? `${question.length}/${followupMode ? 1000 : 2000}` : 'Enter 发送，Shift + Enter 换行' }}</span><button v-if="busy" class="send-button stop-button" type="button" title="停止任务" aria-label="停止任务" :disabled="cancelling" @click="cancel"><AgentIcon name="stop" :size="16" /></button><button v-else class="send-button" title="发送任务" aria-label="发送任务" :disabled="!question.trim() || submitting"><AgentIcon :name="submitting ? 'clock' : 'arrow'" :size="19" /></button></div></form><div v-if="!active" class="starter-grid"><button v-for="item in suggestions" :key="item.title" @click="useSuggestion(item.text)"><AgentIcon :name="item.icon" :size="18" /><span>{{ item.title }}<small>{{ item.detail }}</small></span><AgentIcon name="chevron" :size="13" /></button></div><p class="composer-disclaimer">共享软件演示数据 · 操作与建议分别记录<span> · </span>支持观测核验、视觉与业务记录查询</p></div>
    </div>

    <Transition name="inspector"><aside v-if="evidenceOpen" class="evidence-panel" aria-label="任务依据"><header><span><AgentIcon name="book" :size="18" />任务依据</span><button class="icon-button" aria-label="关闭任务依据" @click="evidenceOpen = false"><AgentIcon name="close" :size="18" /></button></header><div class="evidence-scroll"><div class="evidence-context"><span class="section-label">当前数据范围</span><strong>{{ activeFarmLabel }}</strong><p>共享演示数据 · 当前环境观测</p></div><div class="evidence-heading"><h2>参考资料</h2><span>{{ evidence.length }} 条</span></div><details v-for="(item, i) in evidence" :key="i" class="evidence-card" open><summary><span class="source-number">{{ i + 1 }}</span><strong>{{ item.source }}</strong><AgentIcon name="chevron" :size="13" /></summary><div><span class="source-tag">关键词检索</span><p>{{ item.content }}</p></div></details><div v-if="!evidence.length" class="evidence-empty"><AgentIcon name="book" :size="32" /><h3>还没有参考资料</h3><p>任务执行检索后，资料原文<br>和来源会出现在这里。</p></div><div class="evidence-note"><AgentIcon name="leaf" :size="17" /><p>当前提供资料、阈值与已保存视觉结果核验，病害概率和采后执行尚未接入。</p></div></div></aside></Transition>
