    <Transition name="dialog"><div v-if="panelOpen" class="panel-overlay" @click.self="panelOpen = false"><section ref="panelDialog" @keydown="trapFocus" class="personal-panel" role="dialog" aria-modal="true" aria-label="我的工作面板"><header class="panel-toolbar"><div><AgentIcon name="panel" :size="19" /><strong>我的工作面板</strong><span>{{ panelError || (panelSaving ? '正在保存…' : panelReady ? '已同步' : '正在加载…') }}</span></div><div><select :value="activeWorkbenchId" aria-label="选择工作面板" @change="selectWorkbench(($event.target as HTMLSelectElement).value)"><option v-for="board in workbenches" :key="board.id" :value="board.id">{{ board.name }}</option></select><button class="icon-button" aria-label="新建工作面板" @click="createWorkbench()"><AgentIcon name="plus" /></button><button class="icon-button" aria-label="关闭工作面板" @click="panelOpen = false"><AgentIcon name="close" /></button></div></header><div class="panel-canvas"><PersonalizedWorkbench v-if="activeWorkbench" :key="activeWorkbench.id" :workbench="activeWorkbench" @add="addWidget" @remove="removeWidget" @update="updateWidget" @move="moveWidget" @rename="renameActiveWorkbench" @duplicate="duplicateActiveWorkbench" @delete="deleteActiveWorkbench" @clear="clearActiveWorkbench" @toggle-pin="toggleActivePinned" /><div v-else class="panel-empty"><h2>创建你的农业工作面板</h2><p>组合环境、设备、灌溉与告警组件。</p><button class="new-session" @click="createWorkbench()">创建工作面板</button></div></div></section></div></Transition>
