.session-sidebar{transition:margin-left .38s cubic-bezier(.22,1,.36,1),visibility .38s}.conversation-workspace{transition:width .38s}.welcome-panel{animation:arrive .55s cubic-bezier(.22,1,.36,1) both}.composer-dock{animation:arrive .55s .07s cubic-bezier(.22,1,.36,1) both}.starter-grid button{transition:transform .25s,box-shadow .25s,background .2s}.starter-grid button:hover{transform:translateY(-3px);box-shadow:0 6px 16px #18244008}.send-button{transition:transform .2s,background .2s}.send-button:not(:disabled):hover{transform:scale(1.08)}.agent-app button:active{transform:scale(.97)}summary>svg:last-child{transition:transform .26s}.transcript{animation:arrive .32s ease both}.tool-step{animation:arrive .3s ease both}.inspector-enter-active,.inspector-leave-active{transition:opacity .28s,transform .36s cubic-bezier(.22,1,.36,1),margin-right .36s cubic-bezier(.22,1,.36,1)}.inspector-enter-from,.inspector-leave-to{opacity:0;transform:translateX(30px);margin-right:-320px}.dialog-enter-active,.dialog-leave-active{transition:opacity .24s}.dialog-enter-active .settings-dialog,.dialog-leave-active .settings-dialog,.dialog-enter-active .personal-panel,.dialog-leave-active .personal-panel{transition:transform .32s cubic-bezier(.22,1,.36,1)}.dialog-enter-from,.dialog-leave-to{opacity:0}.dialog-enter-from .settings-dialog,.dialog-leave-to .settings-dialog,.dialog-enter-from .personal-panel,.dialog-leave-to .personal-panel{transform:translateY(18px) scale(.975)}
.panel-overlay{position:absolute;inset:0;z-index:150;display:flex;align-items:center;justify-content:center;padding:28px;background:#18244050;backdrop-filter:blur(8px)}.personal-panel{width:min(1250px,100%);height:calc(100dvh - 56px);background:var(--bg);border:1px solid var(--border);border-radius:20px;overflow:hidden;box-shadow:0 30px 100px #101b3b40;display:flex;flex-direction:column}.panel-toolbar{height:66px;flex-shrink:0;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 23px;gap:14px}.panel-toolbar>div{display:flex;align-items:center;gap:12px}.panel-toolbar strong{font-size:14px;font-weight:600}.panel-toolbar span{font-size:11px;color:var(--muted)}.panel-toolbar select{max-width:200px;background:var(--sidebar);color:var(--text);border:1px solid var(--border);padding:8px 12px;border-radius:8px;font:inherit;font-size:12px}.panel-canvas{flex:1;overflow:auto;padding:24px;background:var(--ui-subtle);color:var(--ui-ink)}.dark .panel-canvas{background:var(--ui-subtle)}.panel-empty{text-align:center;padding:70px 20px}.panel-empty .new-session{margin:25px auto;width:200px}
